values.value:
{
  "CarRentalDriver": {
    "required": [
      "fullName",
      "email",
      "licenceNumber",
      "licenceDate",
      "age"
    ],
    "validators": {
      "licenceNumber": [
        {
          "validator": "ValidateLicenceFormat",
          "message": "CarRental_err_licenceFormat"
        }
      ]
    },
    "pageValidators": [
      {
        "validator": "ValidateLicenceAge",
        "message": "CarRental_err_licenceAge"
      }
    ],
    "hideProgress": true,
    "navigationByChild": true
  },
  "CarRentalCar": {
    "required": [
      "pickupDate",
      "days",
      "bookedThrough"
    ],
    "if (not(carClass='luxury'))": {
      "hidden": [
        "fullInsurance",
        "luxuryNotes"
      ]
    },
    "if (carClass='luxury')": {
      "ticked": [
        "fullInsurance"
      ]
    },
    "hideProgress": true,
    "navigationByChild": true
  },
  "CarRentalInvoice": {
    "required": [
      "billingContact"
    ],
    "hideProgress": true,
    "navigationByChild": true
  },
  "CarRentalExtras": {
    "required": [
      "notes"
    ],
    "hideProgress": true,
    "navigationByChild": true
  },
  "CarRentalSummary": {
    "navigationByChild": true,
    "hideProgress": true
  }
}
